completion.content:
The candidate files must be read and compared against both the cable subject and the derived prior month before the bill amount can be selected.

```python
receipt_file_records = []
for candidate_path in receipt_path_candidates:
    receipt_file_records.append(apis.file_system.show_file(file_path=candidate_path, access_token=file_system_access_token))
def marks_last_month(text):
    lowered = text.lower()
    year_text = str(last_year)
    numeric_markers = [f'{last_year:04d}-{last_month:02d}', f'{last_year:04d}/{last_month:02d}', f'{last_year:04d}_{last_month:02d}', f'{last_year:04d}{last_month:02d}']
    if any(marker in lowered for marker in numeric_markers):
        return True
    if year_text in lowered and (last_month_name.lower() in lowered or last_month_name[:3].lower() in lowered):
        return True
    leading_month_markers = [f'{last_month:02d}/', f'{last_month}/', f'{last_month:02d}-', f'{last_month}-']
    return year_text in lowered and any(marker in lowered for marker in leading_month_markers)
scored_receipts = []
for file_record in receipt_file_records:
    combined_text = file_record['path'] + '\n' + file_record['content']
    lowered = combined_text.lower()
    if 'cable' not in lowered or not marks_last_month(combined_text):
        continue
    score = 10
    score += 6 if 'cable' in file_record['path'].lower() else 3
    score += 4 if 'receipt' in lowered else 0
    score += 2 if 'paid' in lowered else 0
    score += 1 if 'bill' in lowered else 0
    scored_receipts.append((score, file_record))
if not scored_receipts:
    raise RuntimeError('No cable receipt could be grounded to the previous calendar month')
highest_receipt_score = max(score for score, _ in scored_receipts)
top_receipts = [record for score, record in scored_receipts if score == highest_receipt_score]
if len(top_receipts) != 1:
    raise RuntimeError('The previous-month cable receipt is ambiguous')
selected_receipt = top_receipts[0]
def first_numeric_value(fragment):
    buffer = ''
    started = False
    for character in fragment:
        if character.isdigit():
            buffer += character
            started = True
        elif started and character in '.,':
            buffer += character
        elif started:
            break
    cleaned = buffer.replace(',', '').rstrip('.')
    if not cleaned or cleaned.count('.') > 1:
        return None
    value = float(cleaned)
    return value if value > 0 else None
def extract_receipt_amount(content):
    lowered = content.lower()
    amount_markers = ['total amount paid', 'amount paid', 'grand total', 'total due', 'amount due', 'total amount', 'balance due', 'total', 'amount']
    for marker in amount_markers:
        search_from = 0
        while True:
            marker_index = lowered.find(marker, search_from)
            if marker_index < 0:
                break
            line_end = content.find('\n', marker_index)
            if line_end < 0:
                line_end = min(len(content), marker_index + len(marker) + 80)
            value = first_numeric_value(content[marker_index + len(marker):line_end])
            if value is not None:
                return value
            search_from = marker_index + len(marker)
    dollar_index = content.find('$')
    if dollar_index >= 0:
        return first_numeric_value(content[dollar_index + 1:dollar_index + 40])
    return None
bill_total = extract_receipt_amount(selected_receipt['content'])
if bill_total is None or bill_total <= 0:
    raise RuntimeError('Unable to derive a positive bill total from the selected receipt')
print({'eligible_receipt_paths': [record['path'] for _, record in scored_receipts], 'selected_receipt_path': selected_receipt['path'], 'derived_bill_total': bill_total})
